<?php $pageTitle='Registrasi Pasien Baru'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Administrator SIMRS']);
$msg='';$error='';$result=null;$clinics=$pdo->query("SELECT id,name FROM master_clinics WHERE active=1 ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nik=trim($_POST['nik']??'');$name=trim($_POST['name']??'');$dob=$_POST['dob']??'';$gender=$_POST['gender']??'';$clinicId=(int)($_POST['clinic_id']??0);
 if(strlen(preg_replace('/\D/','',$nik))<8||strlen($name)<3||!$dob||!in_array($gender,['L','P'],true)||!$clinicId){$error='Data identitas dan tujuan layanan wajib dilengkapi.';} else {
  $s=$pdo->prepare("SELECT * FROM patients WHERE nik=? OR (LOWER(name)=LOWER(?) AND dob=?) LIMIT 1");$s->execute([$nik,$name,$dob]);$existing=$s->fetch();
  if($existing){$error='Pasien telah ditemukan pada sistem dengan No. RM '.$existing['medical_record_no'].'. Gunakan Registrasi Pasien Lama atau lakukan validasi identitas.';}
  else { try{$pdo->beginTransaction();$next=(int)$pdo->query("SELECT COALESCE(MAX(id),0)+1 FROM patients")->fetchColumn();$rm='RM'.date('Y').str_pad((string)$next,5,'0',STR_PAD_LEFT);$pdo->prepare("INSERT INTO patients(medical_record_no,nik,name,dob,gender,phone,address,blood_type,marital_status,emergency_contact) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$rm,$nik,$name,$dob,$gender,trim($_POST['phone']??''),trim($_POST['address']??''),trim($_POST['blood_type']??''),trim($_POST['marital_status']??''),trim($_POST['emergency_contact']??'')]);$pid=(int)$pdo->lastInsertId();$c=$pdo->prepare("SELECT * FROM master_clinics WHERE id=? AND active=1");$c->execute([$clinicId]);$clinic=$c->fetch();if(!$clinic)throw new RuntimeException('Unit layanan tidak tersedia.');$queue=next_queue($pdo,$clinicId);$v=$pdo->prepare("INSERT INTO visits(patient_id,clinic_id,clinic,doctor,queue_no,service_type,status,notes) VALUES(?,?,?,?,?,'Rawat Jalan','Terdaftar',?)");$v->execute([$pid,$clinicId,$clinic['name'],trim($_POST['doctor']??''),$queue,'Registrasi pasien baru']);$visitId=(int)$pdo->lastInsertId();audit($pdo,'CREATE_PATIENT','patients',$pid,'Pasien baru '.$rm.' • registrasi '.$clinic['name']);audit($pdo,'CREATE_VISIT','visits',$visitId,'Kunjungan pertama • antrean '.$queue);$pdo->commit();$result=['rm'=>$rm,'queue'=>$queue,'clinic'=>$clinic['name'],'name'=>$name];$msg='Registrasi pasien berhasil disimpan.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Transaksi tidak dapat diselesaikan: '.$e->getMessage();}}
 }
}
include 'partials/header.php'; ?>
