Pilih unit</option><?php foreach($clinics as $c): ?><option value="<?=$c['id']?>" <?=((int)($_POST['clinic_id']??0)==(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><div><label>Dokter Tujuan</label><input name="doctor" value="<?=e($_POST['doctor']??'')?>" placeholder="Nama dokter / sesuai jadwal klinik"></div><div class="full"><label>Keterangan Administratif</label><textarea name="administrative_note" placeholder="Catatan singkat terkait pendaftaran atau kebutuhan administrasi"></textarea></div></div><div style="margin-top:16px;display:flex;justify-content:flex-end"><button class="btn">Simpan Registrasi & Terbitkan Antrean</button></div></form></div></div>
